// ==========================================
// 3. Curved Translucent Glass Canopy & Walls (Refinement 1)
// ==========================================
const glasshouse = createPivot('GlassEnclosure', [0, 0, 0], root);

// Full-coverage curved glass vault spanning continuously to side walls
const glassRoofGeo = parametricSurface(
  (u, v) => {
    const x = u;
    const z = v;
    const halfWidth = 1.34;
    const absU = Math.min(1.0, Math.abs(z / halfWidth));
    let y;
    if (absU > 0.85) {
      const wallT = (absU - 0.85) / 0.15;
      y = 1.85 + (1.92 - 1.85) * (1 - wallT);
    } else {
      const roofU = absU / 0.85;
      const archProfile = Math.pow(Math.cos(roofU * Math.PI * 0.5), 0.75);
      y = 1.85 + (3.23 - 1.85) * archProfile;
    }
    return [x, y, z];
  },
  { u: [-1.8, 1.8], v: [-1.34, 1.34], uSegments: 24, vSegments: 36 }
);
createPart('GlassVaultRoof', glassRoofGeo, glassMat, { parent: glasshouse });

// Molded eave cornices and gutters along both flanks
[-1.34, 1.34].forEach((zSide, sIdx) => {
  // Eave molding rail
  const eavePts = [[-1.85, 1.85, zSide], [1.85, 1.85, zSide]];
  const eaveGeo = pipeAlongPath(eavePts, 0.032, { tubularSegments: 16, radialSegments: 6 });
  createPart(`EaveCornice_${sIdx}`, eaveGeo, ironMat, { parent: structure });

  // Side wall glass bays and iron mullions
  for (let b = 0; b < 4; b++) {
    const bx = -1.35 + b * 0.9;
    createPart(`GlassWallBay_${sIdx}_${b}`, boxGeo(0.84, 1.42, 0.015), glassMat,
      { position: [bx, 1.13, zSide], parent: glasshouse });
    if (b < 3) {
      createPart(`WallMullion_${sIdx}_${b}`, boxGeo(0.04, 1.44, 0.035), ironDarkMat,
        { position: [bx + 0.45, 1.13, zSide], parent: glasshouse });
    }
  }
});

// Rear Apsidal Wall Glazing & Tracery
createPart('RearGlassBay_L', boxGeo(0.015, 1.42, 0.55), glassMat,
  { position: [-1.80, 1.13, -0.65], parent: glasshouse });
createPart('RearGlassBay_C', boxGeo(0.015, 1.95, 0.65), glassMat,
  { position: [-1.80, 1.38, 0], parent: glasshouse });
createPart('RearGlassBay_R', boxGeo(0.015, 1.42, 0.55), glassMat,
  { position: [-1.80, 1.13, 0.65], parent: glasshouse });
// Rear arched tympanum glass
createPart('RearTympanumGlass', boxGeo(0.015, 0.85, 1.35), glassMat,
  { position: [-1.80, 2.50, 0], parent: glasshouse });

[-0.35, 0.35].forEach((zp, pIdx) => {
  createPart(`RearPost_${pIdx}`, cylinderGeo(0.03, 0.03, 2.5, 8), ironMat,
    { position: [-1.80, 1.63, zp], parent: structure });
});

// Front Facade Entrance Portal & Tracery
[-0.85, 0.85].forEach((zp, fIdx) => {
  createPart(`FrontFlankGlass_${fIdx}`, boxGeo(0.015, 1.42, 0.45), glassMat,
    { position: [1.80, 1.13, zp], parent: glasshouse });
  createPart(`FrontFlankMullion_${fIdx}`, boxGeo(0.04, 1.44, 0.04), ironMat,
    { position: [1.80, 1.13, zp], parent: structure });
  // Upper curved flank glass filling under the arch
  createPart(`FrontFlankUpperGlass_${fIdx}`, boxGeo(0.015, 0.45, 0.45), glassMat,
    { position: [1.80, 2.05, zp], parent: glasshouse });
});

// Front Portal Arch Header & Art Nouveau Glass Canopy
const portalHeaderPts = [
  [1.80, 2.25, -0.48],
  [1.80, 2.50, -0.25],
  [1.80, 2.58, 0.0],
  [1.80, 2.50, 0.25],
  [1.80, 2.25, 0.48]
];
const portalArchGeo = pipeAlongPath(portalHeaderPts, 0.035, { tubularSegments: 16, radialSegments: 8 });
createPart('EntrancePortalArch', portalArchGeo, ironMat, { parent: structure });

// Transom glass above entrance door
createPart('TransomGlass', boxGeo(0.015, 0.30, 0.90), glassMat,
  { position: [1.80, 2.39, 0], parent: glasshouse });

// Art Nouveau radiating fanlight tracery over doorway
[-0.30, -0.15, 0.0, 0.15, 0.30].forEach((tz, tIdx) => {
  const spokePts = [
    [1.805, 2.24, tz * 0.4],
    [1.805, 2.50 - Math.abs(tz) * 0.3, tz]
  ];
  const spokeGeo = pipeAlongPath(spokePts, 0.010, { tubularSegments: 8, radialSegments: 6 });
  createPart(`FanlightSpoke_${tIdx}`, spokeGeo, brassMat, { parent: structure });
});

// Art Nouveau Porch Canopy projecting forward over steps
const canopyPts = [
  [1.80, 2.32, -0.52],
  [2.15, 2.28, -0.48],
  [2.22, 2.35, 0.0],
  [2.15, 2.28, 0.48],
  [1.80, 2.32, 0.52]
];
const canopyGeo = pipeAlongPath(canopyPts, 0.025, { tubularSegments: 16, radialSegments: 6 });
createPart('PorchCanopyRim', canopyGeo, brassMat, { parent: structure });
createPart('PorchCanopyGlass', boxGeo(0.35, 0.015, 0.96), glassMat,
  { position: [1.98, 2.30, 0], parent: glasshouse });

