  // ==========================================
  // 6. Vivid Orchid Clusters & Botanical Elements (Refinement 2)
  // ==========================================
  const flora = createPivot('OrchidCollection', [0, 0, 0], root);

  const aerialRootMat = gameMaterial(0xa0bc98, { roughness: 0.8, metalness: 0.0 });
  const yellowOrchidMat = gameMaterial(0xf4c01e, { roughness: 0.38, metalness: 0.08 });

  // Front entrance balustrade cheek-blocks with polished brass finials
  [-0.68, 0.68].forEach((bz, bIdx) => {
    createPart(`StepBalustrade_${bIdx}`, boxGeo(0.65, 0.38, 0.16), stoneMat,
      { position: [2.25, 0.19, bz], parent: plinth });
    createPart(`StepBalustradeCap_${bIdx}`, boxGeo(0.68, 0.04, 0.18), stoneMat,
      { position: [2.25, 0.40, bz], parent: plinth });
    createPart(`StepFinial_${bIdx}`, sphereGeo(0.06, 12, 8), brassMat,
      { position: [2.45, 0.48, bz], parent: plinth });
  });

  // Hanging Art Nouveau brass lanterns along the central vaulted spine
  [-1.0, 0.0, 1.0].forEach((lx, lIdx) => {
    const lanternGroup = createPivot(`PendantLantern_${lIdx}`, [lx, 2.75, 0], flora);
    const dropChainPts = [[0, 0.48, 0], [0, 0, 0]];
    const dropGeo = pipeAlongPath(dropChainPts, 0.005, { tubularSegments: 6, radialSegments: 4 });
    createPart(`LanternDrop_${lIdx}`, dropGeo, brassMat, { parent: lanternGroup });
    createPart(`LanternCap_${lIdx}`, coneGeo(0.09, 0.06, 8), brassMat,
      { position: [0, 0.02, 0], rotation: [180, 0, 0], parent: lanternGroup });
    createPart(`LanternGlobe_${lIdx}`, sphereGeo(0.065, 10, 8), glassMaterial(0xfff6dd, { opacity: 0.6, roughness: 0.1 }),
      { position: [0, -0.06, 0], parent: lanternGroup });
    createPart(`LanternSpire_${lIdx}`, cylinderGeo(0.005, 0.012, 0.08, 6), brassMat,
      { position: [0, -0.15, 0], parent: lanternGroup });
  });

  function addOrchidBlossom(name, position, rotation, scale, petalColorMat, parentNode) {
    const flower = createPivot(name, position, parentNode);
    if (rotation) {
      flower.rotation.set(rotation[0] * Math.PI / 180, rotation[1] * Math.PI / 180, rotation[2] * Math.PI / 180);
    }
    const s = scale || 1.0;

    createPart('Sepal_Top', sphereGeo(0.052 * s, 8, 6), petalColorMat,
      { position: [0, 0.055 * s, 0], scale: [0.75, 1.45, 0.22], parent: flower });

    createPart('Sepal_LL', sphereGeo(0.048 * s, 8, 6), petalColorMat,
      { position: [-0.04 * s, -0.038 * s, 0], rotation: [0, 0, 35], scale: [0.75, 1.35, 0.22], parent: flower });
    createPart('Sepal_LR', sphereGeo(0.048 * s, 8, 6), petalColorMat,
      { position: [0.04 * s, -0.038 * s, 0], rotation: [0, 0, -35], scale: [0.75, 1.35, 0.22], parent: flower });

    createPart('Petal_Left', sphereGeo(0.062 * s, 8, 6), petalColorMat,
      { position: [-0.058 * s, 0.018 * s, 0.005 * s], rotation: [0, 15, 12], scale: [1.25, 0.95, 0.22], parent: flower });
    createPart('Petal_Right', sphereGeo(0.062 * s, 8, 6), petalColorMat,
      { position: [0.058 * s, 0.018 * s, 0.005 * s], rotation: [0, -15, -12], scale: [1.25, 0.95, 0.22], parent: flower });

    createPart('Labellum_Lip', sphereGeo(0.044 * s, 8, 6), orchidLipMat,
      { position: [0, -0.045 * s, 0.022 * s], rotation: [-25, 0, 0], scale: [1.0, 1.25, 0.55], parent: flower });

    createPart('Column_Crest', cylinderGeo(0.013 * s, 0.009 * s, 0.028 * s, 6), orchidCenterMat,
      { position: [0, -0.006 * s, 0.016 * s], rotation: [45, 0, 0], parent: flower });

    return flower;
  }

  function addOrchidRosette(name, position, parentNode) {
    const rosette = createPivot(name, position, parentNode);
    const leafAngles = [10, 65, 125, 185, 245, 305];
    leafAngles.forEach((ang, idx) => {
      const rad = ang * Math.PI / 180;
      const lx = Math.cos(rad) * 0.19;
      const lz = Math.sin(rad) * 0.19;
      createPart(`Leaf_${idx}`, boxGeo(0.28, 0.012, 0.075), leafMat,
        { position: [lx, 0.035 - idx * 0.004, lz], rotation: [-18 * Math.sin(rad), -ang, 22 * Math.cos(rad)], parent: rosette });
    });
    return rosette;
  }

  const orchidClustersConfig = [
    { x: -1.1, z: -0.95, y: 0.76, mat: magentaOrchidMat, flowers: 5, rotY: 25 },
    { x: -0.5, z: -0.90, y: 0.76, mat: yellowOrchidMat, flowers: 5, rotY: -15 },
    { x: 0.1, z: -0.98, y: 0.76, mat: whiteOrchidMat, flowers: 5, rotY: 40 },
    { x: 0.7, z: -0.92, y: 0.76, mat: purpleOrchidMat, flowers: 5, rotY: -30 },

    { x: -1.1, z: 0.95, y: 0.76, mat: purpleOrchidMat, flowers: 5, rotY: -20 },
    { x: -0.5, z: 0.90, y: 0.76, mat: magentaOrchidMat, flowers: 5, rotY: 35 },
    { x: 0.1, z: 0.98, y: 0.76, mat: yellowOrchidMat, flowers: 5, rotY: -10 },
    { x: 0.7, z: 0.92, y: 0.76, mat: whiteOrchidMat, flowers: 5, rotY: 25 },

    { x: -0.2, z: 0.0, y: 0.88, mat: yellowOrchidMat, flowers: 4, rotY: 180 },
    { x: -0.2, z: 0.0, y: 1.36, mat: magentaOrchidMat, flowers: 5, rotY: 0 }
  ];

  orchidClustersConfig.forEach((cfg, cIdx) => {
    const cluster = createPivot(`Cluster_${cIdx}`, [cfg.x, cfg.y, cfg.z], flora);
    addOrchidRosette(`Rosette_${cIdx}`, [0, 0, 0], cluster);

    // Cascading aerial roots spilling over the planter edge
    [-0.1, 0.1].forEach((rx, rIdx) => {
      const rootPts = [
        [rx, 0.01, 0],
        [rx * 1.4, -0.12, (cfg.z < 0 ? 0.18 : -0.18)],
        [rx * 1.8, -0.26, (cfg.z < 0 ? 0.22 : -0.22)]
      ];
      const rootGeo = pipeAlongPath(rootPts, 0.005, { tubularSegments: 10, radialSegments: 4 });
      createPart(`AerialRoot_${cIdx}_${rIdx}`, rootGeo, aerialRootMat, { parent: cluster });
    });

    const stemPts = [
      [0, 0, 0],
      [0.05, 0.24, 0.02],
      [0.10, 0.46, 0.06],
      [0.18, 0.64, 0.14],
      [0.30, 0.72, 0.22],
      [0.44, 0.67, 0.32]
    ];
    const stemGeo = pipeAlongPath(stemPts, 0.010, { tubularSegments: 20, radialSegments: 6 });
    createPart(`Stem_${cIdx}`, stemGeo, stemMat, { parent: cluster });

    for (let f = 0; f < cfg.flowers; f++) {
      const t = (f + 1) / (cfg.flowers + 1);
      const fx = 0.07 + t * 0.34;
      const fy = 0.38 + Math.sin(t * Math.PI) * 0.35;
      const fz = 0.05 + t * 0.28;
      const fScale = 0.95 + 0.28 * Math.sin(t * Math.PI);
      addOrchidBlossom(
        `Blossom_${cIdx}_${f}`,
        [fx, fy, fz],
        [-10, cfg.rotY + f * 12, 15 - f * 5],
        fScale,
        cfg.mat,
        cluster
      );
    }
  });

  [-0.6, 0.4].forEach((hx, hIdx) => {
    const hangGroup = createPivot(`HangingBasket_${hIdx}`, [hx, 2.35, 0], flora);
    const chainPts = [[0, 0.85, 0], [0, 0, 0]];
    const chainGeo = pipeAlongPath(chainPts, 0.006, { tubularSegments: 8, radialSegments: 4 });
    createPart(`Chain_${hIdx}`, chainGeo, brassMat, { parent: hangGroup });

    createPart(`MossBall_${hIdx}`, sphereGeo(0.12, 10, 8), soilMat,
      { position: [0, 0, 0], parent: hangGroup });
    createPart(`BasketHoopA_${hIdx}`, torusGeo(0.125, 0.006, 6, 16), brassMat,
      { position: [0, 0, 0], parent: hangGroup });
    createPart(`BasketHoopB_${hIdx}`, torusGeo(0.125, 0.006, 6, 16), brassMat,
      { position: [0, 0, 0], rotation: [90, 0, 0], parent: hangGroup });

    // Hanging aerial roots
    for (let ar = 0; ar < 3; ar++) {
      const aAng = (ar * 120 + 30) * Math.PI / 180;
      const aPts = [
        [Math.cos(aAng) * 0.08, -0.08, Math.sin(aAng) * 0.08],
        [Math.cos(aAng) * 0.12, -0.25, Math.sin(aAng) * 0.12],
        [Math.cos(aAng) * 0.10, -0.42, Math.sin(aAng) * 0.10]
      ];
      const aGeo = pipeAlongPath(aPts, 0.004, { tubularSegments: 10, radialSegments: 4 });
      createPart(`HangRoot_${hIdx}_${ar}`, aGeo, aerialRootMat, { parent: hangGroup });
    }

    const hMat = hIdx === 0 ? magentaOrchidMat : yellowOrchidMat;
    const hangStemPts = [
      [0, -0.05, 0],
      [0.08, -0.18, 0.05],
      [0.16, -0.32, 0.12],
      [0.22, -0.48, 0.18]
    ];
    const hangStemGeo = pipeAlongPath(hangStemPts, 0.007, { tubularSegments: 14, radialSegments: 6 });
    createPart(`HangStem_${hIdx}`, hangStemGeo, stemMat, { parent: hangGroup });

    for (let f = 0; f < 3; f++) {
      const hfx = 0.07 + f * 0.06;
      const hfy = -0.15 - f * 0.11;
      const hfz = 0.05 + f * 0.05;
      addOrchidBlossom(`HangBloom_${hIdx}_${f}`, [hfx, hfy, hfz], [25, 45, 10], 0.90, hMat, hangGroup);
    }
  });

  return root;
}

