        [-10, cfg.rotY + f * 12, 15 - f * 5],
        fScale,
        cfg.mat,
        cluster
      );
    }
  });

  [-0.6, 0.4].forEach((hx, hIdx) => {
    const hangGroup = createPivot(`HangingBasket_${hIdx}`, [hx, 2.35, 0], flora);
    const chainPts = [[0, 0.85, 0], [0, 0, 0]];
    const chainGeo = pipeAlongPath(chainPts, 0.006, { tubularSegments: 8, radialSegments: 4 });
    createPart(`Chain_${hIdx}`, chainGeo, brassMat, { parent: hangGroup });

    createPart(`MossBall_${hIdx}`, sphereGeo(0.12, 10, 8), soilMat,
      { position: [0, 0, 0], parent: hangGroup });
    createPart(`BasketHoopA_${hIdx}`, torusGeo(0.125, 0.006, 6, 16), brassMat,
      { position: [0, 0, 0], parent: hangGroup });
    createPart(`BasketHoopB_${hIdx}`, torusGeo(0.125, 0.006, 6, 16), brassMat,
      { position: [0, 0, 0], rotation: [90, 0, 0], parent: hangGroup });

    const hMat = hIdx === 0 ? magentaOrchidMat : whiteOrchidMat;
    const hangStemPts = [
      [0, -0.05, 0],
      [0.08, -0.18, 0.05],
      [0.16, -0.32, 0.12],
      [0.22, -0.48, 0.18]
    ];
    const hangStemGeo = pipeAlongPath(hangStemPts, 0.007, { tubularSegments: 14, radialSegments: 6 });
    createPart(`HangStem_${hIdx}`, hangStemGeo, stemMat, { parent: hangGroup });

    for (let f = 0; f < 3; f++) {
      const hfx = 0.07 + f * 0.06;
      const hfy = -0.15 - f * 0.11;
      const hfz = 0.05 + f * 0.05;
      addOrchidBlossom(`HangBloom_${hIdx}_${f}`, [hfx, hfy, hfz], [25, 45, 10], 0.85, hMat, hangGroup);
    }
  });

  return root;
}

edits.newString:
function evalRoofSurface(u, v) {
  const xMin = -3.4;
  const xMax = 4.0;
  const x = xMin + u * (xMax - xMin);

  // Transverse parameter zn in [-1, 1]
  const zn = (v - 0.5) * 2.0;

  // Longitudinal spine height: low eaves at u=0 (y=2.05m),
  // arch peak at u=0.42 (y=3.35m), and soaring upward curl toward u=1.0 (y=4.45m).
  const spineY = 2.05 + 1.25 * Math.sin(Math.min(1.0, u * 2.1) * Math.PI * 0.5) +
                 1.35 * Math.pow(Math.max(0, u - 0.32) / 0.68, 2.6);

  // Vault camber: highest in center, dropping toward edges
  const vaultCamber = -0.36 * (zn * zn);

  // Asymmetrical flare and 3D ribbon twist at the curling end
  const ribbonTwist = 0.52 * Math.pow(u, 2.2) * zn;

  const y = spineY + vaultCamber + ribbonTwist;

  // Flaring transverse width: expands dynamically toward the soaring open curl
  const widthScale = 1.0 + 0.28 * Math.pow(u, 2.0);
  const z = zn * 2.45 * widthScale;

  return [x, y, z];
}

