function getSpinePoint(u, v) {
  const y = v * height + 0.015 * Math.sin(u * Math.PI) * (1 - v);
  const arcRadius = 0.158;
  const theta = u * 1.22;
  const z = arcRadius * Math.sin(theta);
  const inwardBulge = 0.026 * Math.sin(u * Math.PI * 0.9);
  const x = -arcRadius * (1 - Math.cos(theta)) - inwardBulge;
  return [x, y, z];
}

