function getSpinePoint(u, v) {
  const y = v * height;
  const arcRadius = 0.165;
  const theta = u * 1.12;
  const z = arcRadius * Math.sin(theta);
  const bulge = 0.032 * Math.sin(u * Math.PI);
  const taper = 1.0 - 0.18 * v;
  const x = (-arcRadius * (1 - Math.cos(theta)) - bulge) * taper;
  return [x, y, z];
}

